CREATE TYPE "PurchaseRequestStatus" AS ENUM ('DRAFT','PENDING','APPROVED','REJECTED','CANCELLED','CONVERTED');
CREATE TYPE "PurchaseOrderStatus" AS ENUM ('DRAFT','ISSUED','PARTIALLY_RECEIVED','RECEIVED','BILLED','CANCELLED');
CREATE TYPE "BillStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','APPROVED','PARTIALLY_PAID','PAID','OVERDUE','VOID');
CREATE TYPE "ExpenseStatus" AS ENUM ('PENDING','APPROVED','REJECTED','VOID');
ALTER TABLE "BankTransaction" ADD COLUMN "sourceType" TEXT, ADD COLUMN "sourceId" UUID;
CREATE TABLE "Supplier" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"displayName" TEXT NOT NULL,"companyName" TEXT,"email" TEXT,"phone" TEXT,"taxId" TEXT,"bankDetails" TEXT,"paymentTerms" TEXT,"address" TEXT,"notes" TEXT,"isActive" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Supplier_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PurchaseRequest" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"number" TEXT NOT NULL,"requestedBy" TEXT NOT NULL,"requiredDate" DATE NOT NULL,"status" "PurchaseRequestStatus" NOT NULL DEFAULT 'DRAFT',"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"items" JSONB NOT NULL,"total" DECIMAL(19,4) NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PurchaseRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PurchaseOrder" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"supplierId" UUID NOT NULL,"requestId" UUID,"number" TEXT NOT NULL,"orderDate" DATE NOT NULL,"deliveryDate" DATE NOT NULL,"status" "PurchaseOrderStatus" NOT NULL DEFAULT 'DRAFT',"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"items" JSONB NOT NULL,"subtotal" DECIMAL(19,4) NOT NULL,"taxTotal" DECIMAL(19,4) NOT NULL DEFAULT 0,"total" DECIMAL(19,4) NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PurchaseOrder_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Bill" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"supplierId" UUID NOT NULL,"purchaseOrderId" UUID,"number" TEXT NOT NULL,"issueDate" DATE NOT NULL,"dueDate" DATE NOT NULL,"status" "BillStatus" NOT NULL DEFAULT 'DRAFT',"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"items" JSONB NOT NULL,"subtotal" DECIMAL(19,4) NOT NULL,"taxTotal" DECIMAL(19,4) NOT NULL DEFAULT 0,"total" DECIMAL(19,4) NOT NULL,"paidAmount" DECIMAL(19,4) NOT NULL DEFAULT 0,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Bill_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplierPayment" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"supplierId" UUID NOT NULL,"billId" UUID NOT NULL,"bankAccountId" UUID,"reference" TEXT NOT NULL,"paymentDate" DATE NOT NULL,"amount" DECIMAL(19,4) NOT NULL,"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"method" TEXT NOT NULL,"notes" TEXT,"reversedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SupplierPayment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Expense" ("id" UUID NOT NULL,"organizationId" UUID NOT NULL,"supplierId" UUID,"bankAccountId" UUID,"reference" TEXT NOT NULL,"expenseDate" DATE NOT NULL,"merchant" TEXT NOT NULL,"category" TEXT NOT NULL,"amount" DECIMAL(19,4) NOT NULL,"taxAmount" DECIMAL(19,4) NOT NULL DEFAULT 0,"currency" CHAR(3) NOT NULL DEFAULT 'NGN',"status" "ExpenseStatus" NOT NULL DEFAULT 'PENDING',"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Expense_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Supplier_organizationId_email_key" ON "Supplier"("organizationId","email"); CREATE INDEX "Supplier_organizationId_displayName_idx" ON "Supplier"("organizationId","displayName");
