CREATE UNIQUE INDEX "SupplierPayment_organizationId_reference_key" ON "SupplierPayment"("organizationId","reference"); CREATE INDEX "SupplierPayment_organizationId_paymentDate_idx" ON "SupplierPayment"("organizationId","paymentDate");
CREATE UNIQUE INDEX "Expense_organizationId_reference_key" ON "Expense"("organizationId","reference"); CREATE INDEX "Expense_organizationId_status_expenseDate_idx" ON "Expense"("organizationId","status","expenseDate"); CREATE INDEX "BankTransaction_organizationId_sourceType_sourceId_idx" ON "BankTransaction"("organizationId","sourceType","sourceId");
